namespace docking.widgets.filechooser;



using docking;
using docking.widgets.checkbox;
using ghidra.framework.preferences;
using ghidra.util.layout;

class GFileChooserOptionsDialog : ReusableDialogComponentProvider {

	static readonly string SHOW_DOT_FILES_PROPERTY_NAME = "G_FILE_CHOOSER.ShowDotFiles";
	private static readonly string SHOW_DOT_FILES_DEFAULT = "false";

	private JCheckBox showDotFilesCheckBox;

	GFileChooserOptionsDialog() : base("File Chooser Options")
    {

		addWorkPanel(buildComponent());

		addOKButton();
		addCancelButton();
	}

	/* @Override */
	protected void dialogShown() {
		initializeValues();
	}

	private JComponent buildComponent() {
		JPanel panel = new JPanel(new PairLayout());

		showDotFilesCheckBox = new GCheckBox("Show '.' files");
		showDotFilesCheckBox.setToolTipText("When toggled on the file chooser will show files " +
			"with names that begin with a '.' character");
		showDotFilesCheckBox.getAccessibleContext().setAccessibleName("Show Dot Files");
		showDotFilesCheckBox.setSelected(true);

		panel.add(showDotFilesCheckBox);
		panel.getAccessibleContext().setAccessibleName("GFile Chooser Options");
		return panel;
	}

	private void initializeValues() {
		bool showDotFiles = getShowsDotFiles();
		showDotFilesCheckBox.setSelected(showDotFiles);
	}

	/* @Override */
	protected void okCallback() {
		// apply the user changes
		Preferences.setProperty(SHOW_DOT_FILES_PROPERTY_NAME,
			Boolean.toString(showDotFilesCheckBox.isSelected()));
		Preferences.store();

		close();
	}

//==================================================================================================
// Options Getter Methods
//==================================================================================================

	bool getShowsDotFiles() {
		string showDotFilesValue =
			Preferences.getProperty(SHOW_DOT_FILES_PROPERTY_NAME, SHOW_DOT_FILES_DEFAULT, true);
		return Boolean.parseBoolean(showDotFilesValue);
	}
}
